  s['after'][key].append(dict(type='plate',book=book,asset='headneck/images/'+asset+'.jpeg',title=title,citation=cite,src=cite,fa_text=guide+' برش از صفحهٔ چندنماست؛ قطعات حاشیه‌ایِ نمای مجاور، اگر دیده شوند، جزو نمای هدف نیستند.',labels=labels,view=title,en_caption=captions[asset.removeprefix('hn05_u_')],max_h=140,min_img_h=80))
